#//in realtime mode we want to poll the stop time to keep up with the current time 
#if({this.custom.exchange.launchpad.oee.display.mode} = "Realtime",now(60000), addSeconds(addDays(midnight(now(0)),{this.custom.exchange.launchpad.oee.display.rangeDays.stop}),-1))

if value.mode == "Realtime":
	# if realtime/day, return 12:00:00 AM today
	if value.interval == "Day":
		return system.date.midnight(value.now)

	# if realtime/shift, return the start of the selected shift
	elif value.interval == "Shift":
		return value.shiftStart

	# if realtime/hour, still return 12:00:00 AM today, as we don't have data for the current hour yet
	else:
		return system.date.midnight(value.now)

if value.mode == "Historical":
	if value.rangeDays.period != "":
		# if historical, return 12:00:00 AM of whatever day is today + rangeDays.start
		return system.date.addDays(system.date.midnight(system.date.now()),value.rangeDays.start)
	else:
		# if historical but custom time
		return value.customTime.start

