if value.mode == "Realtime":
	# if realtime, return now every 60 seconds
	return value.now

if value.mode == "Historical":
	if value.rangeDays.period != "":
		# if historical and not custom time selected, return 11:59:59 PM of whatever day is today + rangeDays.stop
		return system.date.addSeconds(system.date.addDays(system.date.midnight(system.date.now()),value.rangeDays.stop),-1)
	else:
		# if historical and custom time selected
		return value.customTime.stop

if value.rangeDays.period != "":
